import assert from "node:assert/strict";
import * as fs from "node:fs";
import * as path from "node:path";
import { test } from "node:test";
import { REPO, Sandbox } from "../lib/sandbox.ts";
import { FAKE_LOCAL, MINI_USER, MINI_HOST, VALUE_FORMS } from "../lib/ssh_config.ts";

const CONFIG = path.join(REPO, "host/config");
const BASE = path.join(REPO, "host/config.yaml");
const HEADER =
  "# Generated by host/config from host/config.yaml and ~/.mini-op/config.local.yaml; do not edit.";
const GENERATED = ["ssh_config"];

type T = Parameters<typeof Sandbox.create>[0];

// A sandbox whose ~/.mini-op holds only `local` as config.local.yaml (no dir when undefined).
async function sandbox(t: T, local: string | undefined) {
  const sb = await Sandbox.create(t);
  const dir = path.join(sb.home, ".mini-op");
  fs.rmSync(dir, { recursive: true, force: true });
  if (local !== undefined) {
    fs.mkdirSync(dir, { mode: 0o700 });
    fs.writeFileSync(path.join(dir, "config.local.yaml"), local);
  }
  return { sb, dir, local: path.join(dir, "config.local.yaml") };
}

async function config(t: T, local: string | undefined, args: string[] = []) {
  const s = await sandbox(t, local);
  const r = await s.sb.run(["bash", CONFIG, ...args]);
  return { ...s, r };
}

const read = (dir: string, file: string) => fs.readFileSync(path.join(dir, file), "utf8");
const listed = (dir: string) => fs.readdirSync(dir, { recursive: true }).map(String).sort();

test("the base lists every key, address and account empty", () => {
  const text = fs.readFileSync(BASE, "utf8");
  assert.deepEqual(text.split("\n").filter(l=>l && !l.startsWith("#")), ['mini_host: ""', 'mini_user: ""', "mini_port: 22"]);

  const lines = text.split("\n");
  for (const [i, line] of lines.entries()) {
    if (!/^[a-z_]+:/.test(line)) continue;
    assert.match(lines[i - 1] ?? "", /^# /, `a comment says what ${line} is`);
  }
  for (const key of ["mini_host", "mini_user"]) {
    const at = lines.findIndex((line) => line.startsWith(`${key}:`));
    assert.match(
      lines[at - 1] ?? "",
      /Empty: not set; set it in ~\/\.mini-op\/config\.local\.yaml/,
    );
  }
});

test("writes only ssh_config from the merged config", async (t) => {
  const { r, dir } = await config(t, FAKE_LOCAL);
  assert.equal(r.code, 0, r.stderr);
  assert.equal(r.stdout, `config: wrote ${dir}/ssh_config\n`);
  assert.equal(r.stderr, "");
  assert.deepEqual(listed(dir), ["config.local.yaml", ...GENERATED].sort());
  assert.equal(fs.statSync(dir).mode & 0o777, 0o700);
  for (const file of GENERATED) {
    assert.equal(fs.statSync(path.join(dir, file)).mode & 0o777, 0o600, file);
    assert.equal(read(dir, file).split("\n")[0], HEADER, file);
  }
  assert.equal(
    read(dir, "ssh_config"),
    `${HEADER}\nHost mini\n    HostName ${MINI_HOST}\n    User ${MINI_USER}\n    Port 22\n`,
  );

});

test("another mini port reaches ssh_config", async (t) => {
  const { r, dir } = await config(t, `${FAKE_LOCAL}mini_port: 2222\n`);
  assert.equal(r.code, 0, r.stderr);
  assert.match(read(dir, "ssh_config"), /\n {4}Port 2222\n$/);

});

test("get prints merged scalars without writing", async (t) => {
  const local = FAKE_LOCAL;
  const s = await sandbox(t, local);
  const get = async (key: string) => s.sb.run(["bash", CONFIG, "get", key]);
  const expected: Record<string, string> = {
    mini_host: MINI_HOST,
    mini_user: MINI_USER,
    mini_port: "22",
  };
  for (const [key, value] of Object.entries(expected)) {
    const r = await get(key);
    assert.equal(r.code, 0, r.stderr);
    assert.equal(r.stdout, `${value}\n`, key);
  }
  const unknown = await get("mini_address");
  assert.equal(unknown.code, 1);
  assert.equal(unknown.stderr, "config: unknown key mini_address\n");
  assert.deepEqual(listed(s.dir), ["config.local.yaml"], "get writes nothing");
});

test("every value form reads as the bare value", async (t) => {
  for (const form of VALUE_FORMS) {
    const value = form.replace("x", MINI_USER);
    const { r } = await config(t, `mini_host: ${MINI_HOST}\nmini_user: ${value}\n`, [
      "get",
      "mini_user",
    ]);
    assert.equal(r.code, 0, `${form}: ${r.stderr}`);
    assert.equal(r.stdout, `${MINI_USER}\n`, form);
  }
});

test("no local file exits 1 saying what to fill in", async (t) => {
  for (const args of [[], ["get", "mini_port"]]) {
    const { r, sb, local } = await config(t, undefined, args);
    assert.equal(r.code, 1);
    assert.equal(
      r.stderr,
      `config: no ${local}; create it with mini_host: <the mini's LAN IPv4> and mini_user: ` +
        "<the mini's account> (host/README.md, Steps)\n",
    );
    assert.equal(r.stdout, "");
    assert.ok(!fs.existsSync(path.join(sb.home, ".mini-op")));
  }
});

test("an empty required key exits 1; both are named", async (t) => {
  const cases: [string, string[]][] = [
    [`mini_host: ${MINI_HOST}\n`, ["mini_user"]],
    [`mini_host: ""\nmini_user: ${MINI_USER}\n`, ["mini_host"]],
    ["# nothing set yet\n", ["mini_host", "mini_user"]],
  ];
  for (const [text, keys] of cases) {
    const { r, dir, local } = await config(t, text);
    assert.equal(r.code, 1, text);
    assert.equal(
      r.stderr,
      keys.map((key) => `config: ${key} is empty; set it in ${local}\n`).join(""),
    );
    assert.deepEqual(listed(dir), ["config.local.yaml"]);
  }
});

test("invalid values exit 1 naming the key", async (t) => {
  const cases: [string, RegExp][] = [
    ["mini_host: 8.8.8.8", /^config: mini_host /],
    ["mini_host: 192.168.001.20", /^config: mini_host /],
    ["mini_host: 10.9.8.256", /^config: mini_host /],
    ["mini_host: 172.32.0.1", /^config: mini_host /],
    ["mini_host: mini.local", /^config: mini_host /],
    ["mini_user: Tester", /^config: mini_user /],
    ["mini_user: a.b", /^config: mini_user /],
    ["mini_port: 0", /^config: mini_port /],
    ["mini_port: 022", /^config: mini_port /],
    ["mini_port: 65536", /^config: mini_port /],
  ];
  for (const [line, message] of cases) {
    const key = line.slice(0, line.indexOf(":"));
    const rest = FAKE_LOCAL.split("\n").filter((l) => l && !l.startsWith(`${key}:`));
    const { r, dir } = await config(t, [...rest, line, ""].join("\n"));
    assert.equal(r.code, 1, line);
    assert.match(r.stderr, message, line);
    assert.deepEqual(listed(dir), ["config.local.yaml"], line);
  }
  for (const host of ["172.16.0.1", "172.31.255.254", "192.168.0.9", "10.0.0.0"]) {
    const { r } = await config(
      t,
      `mini_host: ${host}\nmini_user: ${MINI_USER}\nmini_port: 65535\n`,
    );
    assert.equal(r.code, 0, `${host}: ${r.stderr}`);
  }
});

test("malformed lines, duplicate keys and kind mismatches exit 1 with file:line", async (t) => {
  const cases: [string, number][] = [
    ["  mini_port: 22", 3],
    ["- claude.ai", 3],
    ["mini_port: 2#2", 3],
    ['mini_port: "22"x', 3],
    ["mini_port: [22", 3],
    ["Mini_port: 22", 3],
    ["mini_port: 22\n\nmini_port: 23", 5],
    ["mini_port: [22]", 3],
  ];
  for (const [lines, line] of cases) {
    const { r, dir, local } = await config(t, `${FAKE_LOCAL}${lines}\n`);
    assert.equal(r.code, 1, lines);
    assert.ok(r.stderr.startsWith(`config: ${local}:${line}: `), `${lines}: ${r.stderr}`);
    assert.deepEqual(listed(dir), ["config.local.yaml"], lines);
  }
});

test("an unknown local key exits 1 and writes nothing", async (t) => {
  const { r, dir, local } = await config(t, `${FAKE_LOCAL}mini_address: ${MINI_HOST}\n`);
  assert.equal(r.code, 1);
  assert.equal(
    r.stderr,
    `config: ${local}:3: unknown key mini_address; host/config.yaml lists the keys\n`,
  );
  assert.deepEqual(listed(dir), ["config.local.yaml"]);
});

test("an existing ~/.mini-op keeps its mode", async (t) => {
  const s = await sandbox(t, FAKE_LOCAL);
  fs.chmodSync(s.dir, 0o755);
  assert.equal((await s.sb.run(["bash", CONFIG])).code, 0);
  assert.equal(fs.statSync(s.dir).mode & 0o777, 0o755);
});

test("-h prints the usage; other arguments are usage errors", async (t) => {
  const s = await sandbox(t, FAKE_LOCAL);
  const help = await s.sb.run(["bash", CONFIG, "-h"]);
  assert.equal(help.code, 0);
  assert.match(help.stdout, /^config \[get <key>\]/);
  for (const args of [["get"], ["get", "a", "b"], ["x"], ["policy-hash", "x"], ["-h", "x"]]) {
    const r = await s.sb.run(["bash", CONFIG, ...args]);
    assert.equal(r.code, 2, args.join(" "));
    assert.equal(r.stderr, "config: usage: config [get <key>]\n");
  }
  assert.deepEqual(listed(s.dir), ["config.local.yaml"]);
});
